export const STEPS = STEPS_5STAR;

/** First main-path step index where the branch trace diverges (fork token, e.g. "this" vs "a"). */
export const BRANCH_FROM_5_INDEX = 3;

/** Main-path step index where the 5★→1★ switch button is shown (last shared token before the fork). */
export const BRANCH_SWITCH_FROM_5_INDEX = 2;

/** First main-path step index where the branch trace diverges. */
export const BRANCH_FROM_1_INDEX = 4;

/** Main-path step index where the 1★→5★ switch button is shown. */
export const BRANCH_SWITCH_FROM_1_INDEX = 3;

/** Labels for prompt-only steps (I, really) on the chart. */
export const CHART_PREFIX_LABELS = ["I","really"];

/** Shown in grey before steered decode; generation is appended after this. Override with `fixed_prompt_display` on `steps[0]`. */
export const FIXED_STEER_PROMPT_DISPLAY = '[sos] I really';

export function getFixedSteerPromptDisplay(steps) {
  if (steps?.length && typeof steps[0].fixed_prompt_display === 'string')
    return steps[0].fixed_prompt_display;
  return FIXED_STEER_PROMPT_DISPLAY;
}

export function countPromptOnlySteps(steps) {
  if (!steps?.length) return 0;
  let n = 0;
  for (const s of steps) {
    if (s.prompt_only) n++;
    else break;
  }
  return n;
}

export function branchSwitchStepIndex(mainSteps, branchIndex) {
  if (branchIndex == null || !mainSteps?.length) return null;
  const steerStart = countPromptOnlySteps(mainSteps);
  if (branchIndex <= steerStart) return branchIndex;
  return branchIndex - 1;
}

export function mergeTraceAtBranch(mainSteps, branchSteps, branchIndex) {
  const alignShift = countPromptOnlySteps(mainSteps) - countPromptOnlySteps(branchSteps);
  const branchStart = Math.max(0, branchIndex - alignShift);
  return [...mainSteps.slice(0, branchIndex), ...branchSteps.slice(branchStart)];
}
